from __future__ import annotations

import ast
import io
import re
import tokenize
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

FORBIDDEN_PHRASES = [
    "reproduction of",
    "based on the paper",
    "re-implementation",
    "following the authors",
    "as described by",
    "generated by",
    "ai-assisted",
    "skeleton",
    "placeholder",
    "todo from paper",
    "comprehensive",
    "state-of-the-art",
    "cutting-edge",
    "seamlessly",
    "leveraging",
    "utilize",
    "delve",
    "holistic",
    "meticulously",
    "it's worth noting",
    "in conclusion",
]
STEP_PATTERN = re.compile(r"step\s+\d", re.IGNORECASE)
ROBUST_PATTERN = re.compile(r"\brobust\b", re.IGNORECASE)
EMOJI_PATTERN = re.compile(
    "[\U0001f000-\U0001faff\U00002600-\U000026ff\U00002700-\U000027bf"
    "\U0001f1e6-\U0001f1ff\U00002b00-\U00002bff\U0000fe00-\U0000fe0f]"
)


def _python_files() -> list[Path]:
    return [*(ROOT / "epiresist").rglob("*.py"), *(ROOT / "provings").rglob("*.py")]


def _prose_targets() -> list[Path]:
    files = [p for p in _python_files() if p.name != "test_style_guard.py"]
    return [*files, ROOT / "README.md", ROOT / "Makefile"]


def test_no_comments_in_source():
    for path in _python_files():
        tokens = tokenize.generate_tokens(io.StringIO(path.read_text()).readline)
        comments = [t for t in tokens if t.type == tokenize.COMMENT]
        assert comments == [], f"comment found in {path.name}"


def test_no_docstrings_in_source():
    for path in _python_files():
        tree = ast.parse(path.read_text())
        for node in ast.walk(tree):
            if isinstance(node, (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                assert ast.get_docstring(node) is None, f"docstring in {path.name}"


def test_no_forbidden_phrases():
    for path in _prose_targets():
        text = path.read_text().lower()
        for phrase in FORBIDDEN_PHRASES:
            assert phrase not in text, f"forbidden phrase {phrase!r} in {path.name}"
        assert not STEP_PATTERN.search(text), f"step-number phrasing in {path.name}"
        assert not ROBUST_PATTERN.search(text), f"self-praise 'robust' in {path.name}"


def test_no_emoji():
    for path in _prose_targets():
        assert not EMOJI_PATTERN.search(path.read_text()), f"emoji in {path.name}"
